const ZAMN_SEO_PROFILES = {"aljawab-almajhool":{"title":"لعبة الجواب المجهول | تحدي جماعي أونلاين - العاب زامن","desc":"الجواب المجهول لعبة جماعية من 7 أبواب، في كل باب 15 سؤالًا مختلفًا بدون تكرار بين الأبواب.","lead":"الجواب المجهول لعبة جماعية تعتمد على الخداع والتخمين. يكتب كل لاعب إجابة مضللة، ثم تظهر إجابات اللاعبين مع الإجابة الصحيحة بشكل مجهول. حاول ألا تقع في فخهم واختر الجواب الصحيح.","how":"أنشئ غرفة وشارك رمز الدخول مع اللاعبين، ثم اختر أحد الأبواب السبعة. يظهر السؤال ويكتب كل لاعب إجابة يحاول بها خداع البقية، وبعدها تظهر إجابات اللاعبين مع الإجابة الصحيحة بشكل مجهول. اختر الإجابة التي تعتقد أنها الصحيحة.","keywords":[],"faq":[["ما فكرة اللعبة وكم لاعبًا تحتاج؟","تناسب ثلاثة لاعبين فأكثر. يكتب كل لاعب إجابة خاطئة تبدو مقنعة، ثم يحاول الجميع اكتشاف الجواب الصحيح بين الإجابات المجهولة."],["كيف ندخل وكم عدد الأسئلة؟","ينشئ صاحب الجلسة غرفة ويشارك رابطها أو رمزها. يختار اللاعبون أسماءهم وشخصياتهم. تضم اللعبة سبعة أبواب، في كل باب خمسة عشر سؤالًا."],["هل تحتاج تحميلًا، وهل تعمل على الجوال والشاشة الكبيرة؟","تعمل من المتصفح دون تحميل. يمكن عرض اللعبة على شاشة مشتركة واستخدام الجوالات للمشاركة بحسب طريقة كل لعبة."],["كيف تُحسب النقاط؟","نقطة عند اختيار الجواب الصحيح، ونقطة عن كل لاعب يختار إجابتك المضللة. لا يمكنك اختيار إجابتك أنت."],["ماذا لو كتبت الجواب الصحيح في مرحلة الخداع؟","لن يظهر كفخ للاعبين، لكن يمكنك المشاركة في التصويت. بعد الجولة تظهر النتائج ويتضح من خدع مَن."]]},"horof-bell":{"title":"لعبة حروف وألوف مع جرس | لعبة حروف جماعية - العاب زامن","desc":"العب حروف وألوف مع جرس مدمج وأكثر من 2000 سؤال. لعبة حروف جماعية للجمعات والعائلة والأصدقاء تعمل من المتصفح ويمكن عرضها على التلفزيون بدون تحميل.","lead":"حروف وألوف مع جرس مدمج من العاب زامن هي لعبة حروف جماعية عربية تعتمد على سرعة الإجابة والتنافس بين الفرق، وتضم أكثر من 2000 سؤال. تعمل مباشرة من المتصفح على الجوال والكمبيوتر ويمكن عرضها على التلفزيون.","how":"قسّم اللاعبين إلى فريقين، اعرض اللعبة على شاشة كبيرة، اختر الحروف، ثم تنافسوا على الإجابة. أول فريق يضغط الجرس يحصل على فرصة الإجابة وجمع النقاط.","keywords":[],"faq":[["كيف نبدأ وكم عدد الفرق؟","جهّز فريقين وسمّهما من الإعدادات، واختر حجم الشبكة وعدد جولات الفوز، ثم اضغط «ابدأ اللعب»."],["هل تحتاج تحميلًا، وهل تعمل على الجوال والشاشة الكبيرة؟","تعمل من المتصفح دون تحميل. يمكن عرض اللعبة على شاشة مشتركة واستخدام الجوالات للمشاركة بحسب طريقة كل لعبة."],["هل يوجد مقدم وجرس؟","نعم، تدعم اللعبة شاشة مستقلة للمقدم وجرسًا من جوالات اللاعبين. يتنافس اللاعبون على الإجابة عن الأسئلة المرتبطة بالحروف."],["ما الإعدادات التي أستطيع تغييرها؟","يمكنك تغيير أسماء الفريقين وألوانهما، وحجم الشبكة، وعدد الجولات المطلوبة للفوز، واختيار مقدم آلي أو بشري."],["ما أحجام الشبكة وعدد الجولات؟","تتوفر شبكة ٤×٤ أو ٥×٥ أو ٦×٦، ويمكن تحديد جولات الفوز من جولة واحدة إلى خمس."]]},"horof":{"title":"حروف وألوف أونلاين | لعبة حروف جماعية بدون تحميل - العاب زامن","desc":"حروف وألوف أونلاين لعبة حروف جماعية عربية للعائلة والأصدقاء، تعمل مباشرة من المتصفح بدون تحميل وتناسب الجلسات والتحديات.","lead":"حروف وألوف من العاب زامن لعبة حروف عربية جماعية للفرق والجلسات، مناسبة لمن يريد تجربة مباشرة وبسيطة من المتصفح بدون تحميل.","how":"كوّن فريقين، اختر حرفًا، ثم تنافسوا على الإجابة الصحيحة وجمع أكبر عدد من النقاط.","keywords":[],"faq":[["ما الفرق بين حروف وألوف وحروف مع الجرس؟","هذه النسخة أبسط، بينما نسخة حروف وألوف مع الجرس تضيف جرسًا مدمجًا وتجربة تنافسية أوسع."],["هل تعمل بدون تحميل؟","نعم، تعمل مباشرة من المتصفح."],["هل تناسب العائلة والأصدقاء؟","نعم، مناسبة للجلسات والتحديات الجماعية."],["هل يمكن عرضها على التلفزيون؟","نعم، يمكن عرض اللعبة على شاشة كبيرة أثناء اللعب."]]},"photos-1":{"title":"تحدي الصور | لعبة تخمين الصور وألغاز بصرية - العاب زامن","desc":"تحدي الصور من العاب زامن لعبة تخمين صور وألغاز بصرية للجمعات والعائلة والأصدقاء. اختبر سرعة الملاحظة واربط الصور للوصول إلى الحل، مباشرة من المتصفح بدون تحميل.","lead":"تحدي الصور من العاب زامن لعبة جماعية بصرية تعتمد على تحليل الصور وربط التفاصيل للوصول إلى الإجابة قبل الفريق المنافس. تناسب جمعات العائلة والأصدقاء وتعمل مباشرة من المتصفح.","how":"اعرض الصور على الشاشة، امنح الفرق وقتًا قصيرًا للتفكير، ثم احتسب النقطة لأول فريق يصل إلى الحل الصحيح.","keywords":[],"faq":[["ما فكرة تحدي الصور؟","تحلل الصور والعناصر الظاهرة فيها لتصل إلى الإجابة التي يمثلها التحدي."],["كيف نجهّز الجلسة؟","اختر «جماعي»، واكتب اسمَي الفريقين في طور العرض، ثم اضغط «إنشاء غرفة جديدة»."],["هل تحتاج تحميلًا، وهل تعمل على الجوال والشاشة الكبيرة؟","تعمل من المتصفح دون تحميل. يمكن عرض اللعبة على شاشة مشتركة واستخدام الجوالات للمشاركة بحسب طريقة كل لعبة."],["هل يوجد طور فردي؟","الطور الجماعي متاح في واجهة اللعب الحالية. يظهر زر الفردي بعبارة «قريبًا»."],["هل تشبه خمن الرابط؟","اللعبتان تعتمدان على الصور، لكن لكل منهما واجهتها وتحدياتها. في تحدي الصور تحلل العناصر البصرية للوصول إلى حل اللغز."]]},"photos-2":{"title":"تحدي الصور الجزء الثاني | ألغاز صور وتخمين جماعي - العاب زامن","desc":"تحدي الصور الجزء الثاني يقدم ألغازًا وصورًا جديدة للمنافسة بين الأصدقاء والعائلة، مع تحديات تخمين بصرية تعمل من المتصفح بدون تحميل.","lead":"تحدي الصور الجزء الثاني يضيف مجموعة مختلفة من الألغاز البصرية والتخمينات لمن أنهى الجزء الأول أو يريد تحديات صور جديدة في جلسة جماعية.","how":"اعرض التحدي، حلل الصور مع فريقك، ثم قدّم الإجابة قبل الفريق الآخر. كل جولة تقدم تحديًا بصريًا جديدًا.","keywords":[],"faq":[["هل الجزء الثاني مختلف عن الأول؟","نعم، يحتوي على صور وألغاز وتحديات مختلفة عن الجزء الأول."],["هل أحتاج الجزء الأول للعب؟","لا، يمكن لعب الجزء الثاني بشكل مستقل."],["هل يناسب العائلة والأصدقاء؟","نعم، صُمم للتحديات والجلسات الجماعية."],["هل يعمل على التلفزيون؟","نعم، يمكن عرضه على شاشة كبيرة."],["هل يعمل بدون تحميل؟","نعم، يعمل من المتصفح مباشرة."]]},"photos-3":{"title":"تحدي الصور الجزء الثالث | لعبة تخمين الصور وألغاز بصرية - العاب زامن","desc":"تحدي الصور الجزء الثالث من العاب زامن يقدم ألغازًا بصرية وتحديات تخمين صور جديدة للجمعات والعائلة والأصدقاء، ويعمل مباشرة من المتصفح بدون تحميل.","lead":"تحدي الصور الجزء الثالث يقدم جولات بصرية جديدة لمحبي التخمين وسرعة الملاحظة، مع تحديات مختلفة ومنافسة جماعية مناسبة للعائلة والأصدقاء.","how":"شاهد الصور، ركّز على التفاصيل، واتفق مع فريقك على الحل قبل الفريق المنافس.","keywords":[],"faq":[["هل الجزء الثالث مختلف عن الأول والثاني؟","نعم، يحتوي على مجموعة جديدة من الصور والألغاز والتحديات."],["هل يمكن لعبه بدون الأجزاء السابقة؟","نعم، يمكن لعب الجزء الثالث بشكل مستقل."],["هل يناسب العائلة والأصدقاء؟","نعم، مناسب للجلسات والتحديات الجماعية."],["هل يعمل على الجوال والتلفزيون؟","نعم، يعمل من المتصفح ويمكن عرضه على شاشة كبيرة."],["هل يحتاج تحميل؟","لا، يعمل مباشرة من المتصفح."],["كم عدد اللاعبين؟","يناسب لاعبين أو أكثر ويمكن تقسيم المجموعة إلى فرق."]]},"fawazeer":{"title":"لعبة فوازير وأسئلة | ألغاز وتحديات جماعية - العاب زامن","desc":"لعبة فوازير عربية تضم أسئلة وألغاز وتحديات جماعية للعائلة والأصدقاء. مناسبة للجمعات وتعمل مباشرة من المتصفح بدون تحميل على الجوال والكمبيوتر.","lead":"لعبة فوازير من العاب زامن تجمع الأسئلة والألغاز والتحديات في تجربة عربية جماعية مناسبة للعائلة والأصدقاء والجلسات، وتعمل مباشرة من المتصفح.","how":"قسّم اللاعبين أو العبوا كمجموعة، اعرض الفزورة أو السؤال، ثم احتسب النقاط للإجابة الصحيحة الأسرع.","keywords":[],"faq":[["ما فكرة فوازير وكم عدد الفرق؟","يتنافس فريقان على حل الأسئلة والفوازير، وتضم اللعبة بطاقات خاصة أثناء اللعب."],["كيف نبدأ؟","اكتب اسمَي الفريقين، وجهّز المشاركين، ثم ابدأ الجلسة من واجهة اللعبة."],["هل تحتاج تحميلًا، وهل تعمل على الجوال والشاشة الكبيرة؟","تعمل من المتصفح دون تحميل. يمكن عرض اللعبة على شاشة مشتركة واستخدام الجوالات للمشاركة بحسب طريقة كل لعبة."],["كيف يدخل المقدم واللاعبون؟","تظهر باركودات مستقلة للمقدم ولجرس اللاعبين. يفتح المقدم شاشته، ويدخل اللاعبون إلى الجرس من جوالاتهم."],["كيف نستخدم البطاقات؟","اتبع وصف البطاقة والخيارات المعروضة داخل الجولة عند استخدامها، حتى تكون طريقة اللعب واضحة للفريقين."]]},"family-feud":{"title":"شراء فاميلي فيود بالعربي | لعبة عائلية جماعية - زامن","desc":"فاميلي فيود لفريقين مع شاشة مقدم وجرس من الجوال وسرقة الجولة بعد ٣ أخطاء. اختر عدد الأسئلة، والعب بدون تكرار مع توزيع النقاط تلقائيًا، من المتصفح بدون تحميل.","lead":"تحدّي عائلي بين فريقين لتخمين الإجابات الأكثر شيوعًا، مع شاشة مستقلة للمقدم وجرس من جوالات اللاعبين. بعد ٣ أخطاء، يحصل الفريق المنافس على فرصة سرقة الجولة بإجابة صحيحة واحدة! اختر عدد الأسئلة، والعب أسئلة عشوائية بدون تكرار في الجلسة، مع احتساب النقاط وتوزيعها تلقائيًا. تعمل من المتصفح ويمكن عرضها على التلفزيون بدون تحميل.","how":"سمّ الفريقين واختر عدد الأسئلة، ثم افتح شاشة المقدم وشارك رابط الجرس مع اللاعبين. أول فريق يضغط الجرس يبدأ الإجابة، وبعد ٣ أخطاء يحاول الفريق الآخر سرقة الجولة بإجابة صحيحة واحدة. إذا أخفق في السرقة، تذهب النقاط للفريق الأول تلقائيًا.","keywords":[],"faq":[["كيف نجهّز اللعبة وكم عدد الفرق؟","سمّ فريقين بأسماء مختلفة واختر عدد الأسئلة، ثم شارك باركود المقدم والجرس. تبدأ الجلسة من شاشة المقدم، وأول ضغطة على الجرس تحدد الفريق الذي يبدأ."],["هل تحتاج تحميلًا، وهل تعمل على الجوال والتلفزيون؟","تعمل مباشرة من المتصفح دون تحميل. اعرض لوحة اللعبة على الكمبيوتر أو التلفزيون، وافتح شاشة المقدم والجرس على الجوالات."],["كيف تعمل شاشة المقدم والجرس؟","يرى المقدم الإجابات ويتحكم في كشفها وتسجيل الأخطاء. يدخل اللاعبون إلى الجرس بأسمائهم، ويضغطون لطلب الإجابة؛ لا يمكن تكرار اسم داخل الفريق نفسه."],["متى تتم سرقة الجولة وكيف تُوزّع النقاط؟","بعد ٣ أخطاء للفريق الأول، يحاول الفريق الثاني سرقة الجولة بإجابة صحيحة واحدة. إذا نجح يأخذ نقاط الإجابات المكشوفة، وإذا أخفق تبقى للفريق الأول. تتولى اللعبة توزيع النقاط تلقائيًا."],["هل أختار عدد الأسئلة وهل تتكرر؟","نعم، تحدد عدد الأسئلة قبل البداية. تختار اللعبة الأسئلة عشوائيًا دون تكرار داخل الجلسة نفسها."]]},"guess-link":{"title":"خمن الرابط | لعبة ربط الصور والتخمين الجماعي - العاب زامن","desc":"خمن الرابط لعبة جماعية تعتمد على ربط الصور والوصول إلى الإجابة قبل الفريق المنافس، مناسبة للجمعات وتعمل مباشرة من المتصفح بدون تحميل.","lead":"خمن الرابط من العاب زامن لعبة صور وتفكير جماعية: شاهد العناصر المعروضة واكتشف الفكرة أو الرابط بينها قبل الفريق المنافس.","how":"شاهد مجموعة الصور أو الرموز، ابحث عن الفكرة المشتركة بينها، ثم قدّم الإجابة الأسرع.","keywords":[],"faq":[["ما فكرة اللعبة وكيف نبدأ؟","اكتشف الرابط بين أربع صور. سمّ فريقين بأسماء مختلفة، وجهّز الجلسة وروابط المقدم والجرس، ثم يبدأ المقدم اللعب."],["هل تحتاج تحميلًا، وهل تعمل على الجوال والشاشة الكبيرة؟","تعمل من المتصفح دون تحميل. يمكن عرض اللعبة على شاشة مشتركة واستخدام الجوالات للمشاركة بحسب طريقة كل لعبة."],["ما دور المقدم والجرس؟","يرى المقدم الصور والإجابة، ويكشف الصور واحدة بعد الأخرى. يستخدم اللاعبون الجرس لطلب الإجابة، ويظهر اسم صاحب الضغطة الأولى."],["كيف تُحسب النقاط؟","الإجابة بعد الصورة الأولى تمنح قيمة السؤال كاملة. بعد الثانية يُخصم ٢٥، وبعد الثالثة ٥٠، وبعد الرابعة ٧٥ نقطة. يحدد المقدم الفريق والصورة التي أجاب عندها."],["ماذا يحدث إذا لم يجب أحد؟","يختار المقدم «محد جاوب»، فلا تُمنح نقاط. يصبح السؤال مستخدمًا على اللوحة ثم تنتقلون إلى سؤال آخر."]]},"alatrash":{"title":"مين الأطرش في الزفة | لعبة جماعية مثل برا السالفة - العاب زامن","desc":"مين الأطرش في الزفة لعبة تحرٍ اجتماعية لثلاثة لاعبين فأكثر، تعتمد على اكتشاف صاحب السؤال المختلف في جو من الضحك والذكاء.","lead":"مين الأطرش في الزفة من العاب زامن لعبة اجتماعية تعتمد على الأسئلة والإجابات والملاحظة، ويحاول اللاعبون كشف الشخص الذي حصل على سؤال مختلف.","how":"يحصل معظم اللاعبين على سؤال متقارب بينما يحصل لاعب واحد على سؤال مختلف، ثم يحاول الجميع كشفه من إجاباته وتصرفاته.","keywords":[],"faq":[["ما فكرة اللعبة وكم لاعبًا تحتاج؟","تناسب ثلاثة لاعبين فأكثر. يحصل أحد اللاعبين على سؤال مختلف دون أن يعرف، وتحاول المجموعة اكتشافه من إجاباته."],["كيف ندخل الغرفة؟","ينشئ صاحب الجلسة غرفة ويشارك الباركود أو الرمز. يدخل اللاعب من «أنا لاعب» ويكتب اسمه ورمز الغرفة."],["هل تحتاج تحميلًا، وهل تعمل على الجوال والشاشة الكبيرة؟","تعمل من المتصفح دون تحميل. يمكن عرض اللعبة على شاشة مشتركة واستخدام الجوالات للمشاركة بحسب طريقة كل لعبة."],["كيف نكتشف الأطرش؟","استمعوا إلى الإجابات وقارنوها؛ قد تبدو إجابة اللاعب المختلف خارج الموضوع لأنها مبنية على سؤال آخر."],["هل نكشف نص السؤال مباشرة؟","جوهر التحدي هو الاستنتاج من الإجابات، لذلك ناقشوا ما يقوله اللاعبون وتابعوا خطوات الجولة التي تعرضها اللعبة."]]},"top-ten":{"title":"توب تن | لعبة أسئلة وتحديات جماعية للأصدقاء والعائلة - العاب زامن","desc":"توب تن لعبة أسئلة جماعية ممتعة للأصدقاء والعائلة. اختر الفئات، كوّن فريقك، واكتشف 10 إجابات مخفية واجمع النقاط في تحديات ومسابقات عربية حماسية.","lead":"توب تن هي لعبة أسئلة وتحديات جماعية عربية مصممة للجلسات والأصدقاء والعائلة. يتنافس فريقان في مجموعة متنوعة من الفئات والأسئلة، ويحاول كل فريق اكتشاف 10 إجابات مخفية وجمع أكبر عدد من النقاط.","how":"ادخل الرمز وسجل الفرق ثم اختر الكتقري وابدأ اللعب.","keywords":[],"faq":[["ما فكرة توب تن وكم عدد الفرق؟","يتنافس فريقان على اكتشاف عشر إجابات مخفية لكل سؤال وجمع النقاط."],["كيف نجهّز اللعب؟","سمّ الفريقين واختر عدد الجولات. يختار الفريقان التصنيفات بالتناوب، ثم يدخل المقدم إلى شاشته ويبدأ اللعبة."],["هل تحتاج تحميلًا، وهل تعمل على الجوال والشاشة الكبيرة؟","تعمل من المتصفح دون تحميل. يمكن عرض اللعبة على شاشة مشتركة واستخدام الجوالات للمشاركة بحسب طريقة كل لعبة."],["ما دور المقدم؟","يكشف الإجابات الصحيحة ويسجل الأخطاء وينتقل بين الأسئلة، وتظهر التغييرات على شاشة العرض."],["كيف نكسب التلميحات ونستخدمها؟","إجابتان صحيحتان متتاليتان تمنحان الفريق تلميحًا، والخطأ يقطع التسلسل. يستخدم الفريق صاحب الدور رصيده على إجابة غير مكشوفة لإظهار الحرف الأول ومعلومة عن طول الإجابة أو كلماتها."]]},"mn-ana":{"title":"لعبة من أنا؟ جماعية أونلاين | 3 جولات وجرس - زامن","desc":"العب لعبة من أنا؟ الجماعية من زامن: 3 جولات متنوعة لفريقين، جرس من الجوال، شاشة للمقدم، نقاط ×2 وحذف خيارين. تعمل من المتصفح بدون تحميل.","lead":"لعبة من أنا؟ من زامن هي لعبة جماعية عربية لفريقين تجمع سرعة البديهة والمعرفة والتخمين في ثلاث جولات مختلفة. تعمل مباشرة من المتصفح بدون تحميل، وتدعم جرسًا من الجوال لتحديد أسرع فريق، مع شاشة مستقلة للمقدم وشاشة عرض للجمهور.","how":"قسّم المشاركين إلى فريقين، افتح شاشة العرض أمام الجميع وشاشة المقدم على جهاز منفصل، ثم ابدأ الجولات الثلاث. يضغط اللاعبون الجرس من جوالاتهم عند معرفة الإجابة، ويحتسب المقدم النقاط ويستخدم المميزات الخاصة حسب الجولة.","keywords":[],"faq":[["ما فكرة اللعبة وكم عدد الفرق؟","منافسة بين فريقين تجمع الملاحظة والمعرفة وسرعة الإجابة خلال ثلاث جولات مختلفة."],["ما الجولات الثلاث؟","قراءة عبارات بحروف عربية بلا نقاط، وتخمين الإجابة من أربعة تلميحات، ثم تحديد صاحب المقولة من الخيارات."],["هل تحتاج تحميلًا، وهل تعمل على الجوال والشاشة الكبيرة؟","تعمل من المتصفح دون تحميل. يمكن عرض اللعبة على شاشة مشتركة واستخدام الجوالات للمشاركة بحسب طريقة كل لعبة."],["هل الجولة الأولى بدون نقاط في النتيجة؟","لا، المقصود إزالة النقاط من الحروف العربية لقراءتها. الجولة نفسها لها نقاط تُضاف إلى نتيجة الفريق."],["هل يوجد مقدم وجرس وخيارات مساعدة؟","نعم، توجد شاشة مستقلة للمقدم وجرس للاعبين، مع خيارات مثل مضاعفة النقاط وحذف خيارين بحسب ما يتاح في الجولة."]]},"guess-person":{"title":"خمن الشخصية | لعبة تخمين مشاهير سعوديين - زامن","desc":"خمن الشخصية من زامن لعبة جماعية لفريقين تضم ١٣٠ تحديًا من العين والفم والصوت لمشاهير سعوديين وتدعم المكس والمقدم والجرس من الجوال بدون تحميل.","lead":"خمن الشخصية من زامن لعبة جماعية لفريقين تضم ١٣٠ تحديًا من العين والفم والصوت لمشاهير سعوديين وتدعم المكس والمقدم والجرس من الجوال بدون تحميل.","how":"سمّوا الفريقين واختاروا العين أو الفم أو الصوت أو المكس ثم حددوا عدد الأسئلة ووضع اللعب. شاركوا رابط الجلسة وبعد اكتمال المشاركين ابدأوا التحدي. اكشفوا الإجابة واختاروا الفريق الذي جاوب لتسجيل نقطة لكل سؤال.","keywords":[],"faq":[["ما فكرة خمن الشخصية؟","تتنافسون بين فريقين لمعرفة اسم الشخصية من عينه أو فمه أو صوته وتقدرون تختارون مكس يجمع الأنواع الثلاثة."],["كم عدد الأسئلة وهل نختار عددها؟","تضم اللعبة ١٣٠ تحديًا منها ٤٩ من العين و٣٦ من الفم و٤٥ من الصوت. اختاروا ٥ أو ١٠ أو ١٥ أو ٢٠ سؤالًا أو اكتبوا العدد المناسب ضمن المتاح."],["هل نحتاج مقدم؟","تقدرون تلعبون مع مقدم يشوف الإجابة ويتحكم بالأسئلة والجرس أو بدون مقدم وتحاولون تكتشفون الجواب مع بعض."],["كيف يعمل الجرس؟","في وضع المقدم يدخل كل لاعب باسمه وفريقه من رابط الجرس أو الباركود. تظهر أول ضغطة باسم اللاعب وفريقه ويقفل الجرس على الباقين حتى يعيد المقدم فتحه."],["كيف تحسب النقاط؟","كل سؤال يساوي نقطة واحدة. عند الضغط على التالي تختارون الفريق الذي أجاب أو ولا أحد جاوب ثم تظهر النتائج بعد آخر سؤال."],["هل تعمل على الجوال وتحتاج تحميل؟","تعمل من المتصفح بدون تحميل وتناسب الجوال والكمبيوتر ويمكن عرض اللعبة على شاشة مشتركة."]]}};

const ZAMN_RELATED_GAMES = {"horof-bell":["fawazeer","family-feud","top-ten"],"photos-1":["guess-link","top-ten","family-feud"],"family-feud":["fawazeer","horof-bell","alatrash","top-ten"],"fawazeer":["horof-bell","family-feud","guess-link","top-ten"],"guess-link":["photos-1","fawazeer","family-feud","top-ten"],"alatrash":["family-feud","fawazeer","horof-bell","top-ten"],"top-ten":["guess-link","alatrash","family-feud"],"mn-ana":["top-ten","fawazeer","family-feud"],"aljawab-almajhool":["alatrash","top-ten","fawazeer"],"guess-person":["mn-ana","guess-link","family-feud"]};

function renderSeoRelated(game){
  const gamesBox=document.getElementById("seoRelatedGames");
  const articleBox=document.getElementById("horofBellArticleBox");
  if(!gamesBox || !game)return;

  gamesBox.innerHTML="";

  (ZAMN_RELATED_GAMES[game.slug]||[]).slice(0,3).forEach(slug=>{
    const g=(window.ZAMN_GAMES||[]).find(x=>x.slug===slug);
    if(!g)return;
    const a=document.createElement("a");
    a.className="seo-related-card";
    a.href=gamePath(g);
    a.innerHTML=`<img src="${g.image}" alt="${g.name}" loading="lazy" decoding="async"><span>${g.name}</span>`;
    gamesBox.appendChild(a);
  });

  if(articleBox){
    articleBox.hidden = game.slug !== "horof-bell";
  }
}


function setPageIcon(iconUrl){
  if(!iconUrl)return;
  document.querySelectorAll('link[rel="icon"],link[rel="shortcut icon"],link[rel="apple-touch-icon"]').forEach(link=>link.remove());

  const icon=document.createElement("link");
  icon.rel="icon";
  icon.href=iconUrl;
  document.head.appendChild(icon);

  const shortcut=document.createElement("link");
  shortcut.rel="shortcut icon";
  shortcut.href=iconUrl;
  document.head.appendChild(shortcut);

  const apple=document.createElement("link");
  apple.rel="apple-touch-icon";
  apple.href=iconUrl;
  document.head.appendChild(apple);
}


const GAMES = window.ZAMN_GAMES || [];
const bySlug = slug => GAMES.find(g => g.slug === slug);
const gamePath = game => game?.path || `/game/${game.slug}`;
const gameByPath = pathname => {
  const normalized=(pathname||"/").replace(/\/$/,"") || "/";
  if(normalized==='/khmn'||normalized==='/game/guess-person')return bySlug('guess-person');
  return GAMES.find(g=>gamePath(g).replace(/\/$/,"")===normalized) || null;
};
const homeTitle = document.title;
const pageDescription = document.getElementById("pageDescription");
const canonicalLink = document.getElementById("canonicalLink");
const gameView = document.getElementById("gameView");

document.getElementById("browseBtn")?.addEventListener("click",()=>document.getElementById("games-list")?.scrollIntoView({behavior:"smooth"}));
document.querySelectorAll(".faq-question").forEach(btn=>btn.addEventListener("click",()=>{
  const item=btn.closest(".faq-item"), ans=item.querySelector(".faq-answer"), icon=item.querySelector(".faq-icon");
  const open=ans.classList.contains("open");
  document.querySelectorAll(".faq-answer.open").forEach(x=>x.classList.remove("open"));
  document.querySelectorAll(".faq-icon.open").forEach(x=>x.classList.remove("open"));
  if(!open){ans.classList.add("open");icon.classList.add("open")}
}));

function setText(id, value){
  const el=document.getElementById(id);
  if(el) el.textContent=value || "";
}
function setSEO(game){
  const p=ZAMN_SEO_PROFILES[game.slug]||{};
  const url=`https://zamn.games${gamePath(game)}`;
  document.title=p.title||game.seoTitle||`${game.name} | العاب زامن`;
  if(pageDescription) pageDescription.setAttribute("content",p.desc||game.seoDescription||game.description||"");
  if(canonicalLink) canonicalLink.setAttribute("href",url);

  const setMeta=(selector,attr,value)=>{
    let el=document.querySelector(selector);
    if(!el){
      el=document.createElement("meta");
      if(selector.includes('property=')) el.setAttribute("property",selector.match(/property="([^"]+)"/)[1]);
      else el.setAttribute("name",selector.match(/name="([^"]+)"/)[1]);
      document.head.appendChild(el);
    }
    el.setAttribute(attr,value);
  };
  setMeta('meta[property="og:title"]',"content",p.title||game.name);
  setMeta('meta[property="og:description"]',"content",p.desc||game.description||"");
  setMeta('meta[property="og:url"]',"content",url);
  const imageUrl=game.image ? new URL(game.image, window.location.origin).href : "";
  setMeta('meta[property="og:image"]',"content",imageUrl);
  setMeta('meta[property="og:image:alt"]',"content",`غلاف ${game.name} من العاب زامن`);
  setMeta('meta[name="twitter:card"]',"content","summary_large_image");
  setMeta('meta[name="twitter:title"]',"content",p.title||game.name);
  setMeta('meta[name="twitter:description"]',"content",p.desc||game.description||"");
  setMeta('meta[name="twitter:image"]',"content",imageUrl);
  setMeta('meta[name="twitter:image:alt"]',"content",`غلاف ${game.name} من العاب زامن`);

  setText("gameSeoHeading",`عن ${game.name}`);
  setText("gameSeoLead",p.lead||game.description||"");
  setText("gameSeoHowTitle",`كيف تلعب ${game.name}؟`);
  setText("gameSeoHowText",p.how||"ابدأ اللعبة من المتصفح واتبع التعليمات الظاهرة على الشاشة.");
  const kw=document.getElementById("gameSeoKeywords");
  if(kw){kw.innerHTML="";(p.keywords||[]).forEach(x=>{const s=document.createElement("span");s.textContent=x;kw.appendChild(s);});}
  const fqTitle=document.getElementById("gameSeoFaqTitle");
  if(fqTitle) fqTitle.textContent=`الأسئلة الشائعة حول ${game.name}`;
  const fq=document.getElementById("gameSeoFaq");
  if(fq){
    fq.innerHTML="";
    (p.faq||[]).forEach(([q,a])=>{
      const details=document.createElement("details"); details.className="game-seo-faq-item";
      const summary=document.createElement("summary"); summary.className="game-seo-faq-question";
      const text=document.createElement("span"); text.className="game-seo-faq-question-text"; text.textContent=q;
      const icon=document.createElement("span"); icon.className="game-seo-faq-icon"; icon.setAttribute("aria-hidden","true");
      const answer=document.createElement("div"); answer.className="game-seo-faq-answer";
      const para=document.createElement("p"); para.textContent=a;
      summary.append(text,icon); answer.appendChild(para); details.append(summary,answer); fq.appendChild(details);
    });
  }
}
function resetSEO(){
  document.title=homeTitle;
  if(pageDescription) pageDescription.setAttribute("content","العاب زامن - العاب جماعية عربية");
  if(canonicalLink) canonicalLink.setAttribute("href","https://zamn.games/");
}
function renderShots(game){
  const grid=document.getElementById("retroShotsGrid");
  const section=grid?.closest(".screenshots-panel");
  if(!grid)return;
  grid.innerHTML="";
  const shots=(game.screenshots||[]).filter(Boolean);
  if(!shots.length){
    if(section) section.hidden=true;
    return;
  }
  if(section) section.hidden=false;
  shots.forEach((src,index)=>{
    const btn=document.createElement("button");
    btn.className="retro-shot";
    btn.type="button";
    btn.innerHTML=`<img src="${src}" alt="صورة ${index+1} من داخل ${game.name}" loading="lazy" decoding="async">`;
    btn.addEventListener("click",()=>openLightbox(src, game.name));
    grid.appendChild(btn);
  });
}
function renderReviews(game){
  const grid=document.getElementById("retroReviewsGrid");
  const section=grid?.closest(".reviews-panel");
  if(!grid)return;
  if(grid.reviewCleanup) grid.reviewCleanup();
  grid.innerHTML="";
  const reviews=(game.reviews||[]).filter(r=>r && r.name && [...(r.stars||"")].filter(x=>x==="⭐"||x==="★").length>=4);
  if(!reviews.length){
    if(section) section.hidden=true;
    return;
  }
  if(section) section.hidden=false;
  reviews.forEach(r=>{
    const article=document.createElement("article");
    const safeComment=(r.comment||"").trim();
    article.innerHTML=`<div class="review-head"><strong></strong><span></span></div>${safeComment?`<p></p>`:""}`;
    article.querySelector("strong").textContent=r.name;
    article.querySelector("span").textContent=r.stars||"⭐⭐⭐⭐⭐";
    if(safeComment) article.querySelector("p").textContent=safeComment;
    grid.appendChild(article);
  });
  if(document.body.classList.contains("family-design") && window.setupFamilyReviews) window.setupFamilyReviews(grid, reviews);
}
function renderOtherGames(game){
  const grid=document.getElementById("otherGamesGrid");
  if(!grid)return;
  grid.innerHTML="";
  const squareImages={"family-feud":"https://cdn.files.salla.network/other/681606734/b445d29c-9574-4221-9bd2-63e2374852b4-original.webp","horof-bell":"https://cdn.files.salla.network/other/681606734/755a8663-6941-4d3a-bb00-35c7c9ddfdd7-original.webp","photos-1":"https://cdn.files.salla.network/other/681606734/70607bca-1ac8-4e4e-9243-e7a8d854806d-original.webp","fawazeer":"https://cdn.files.salla.network/other/681606734/66b1d33f-cd78-447f-9af2-8a05703088c8-original.webp","guess-link":"https://cdn.files.salla.network/other/681606734/f20e417f-b98c-4f99-afd9-ab68651f404d-original.webp","alatrash":"https://cdn.files.salla.network/other/681606734/64bb88e4-5671-4581-b1fd-bb30ce3ff07c-original.webp","top-ten":"https://cdn.files.salla.network/other/681606734/32a22b5b-8731-4e9d-8f5d-16ce6ec024aa-original.webp","mn-ana":"https://cdn.files.salla.network/other/681606734/ed5dc929-5c34-469f-9ee4-85a82eb9d00b-original.webp","aljawab-almajhool":"https://cdn.files.salla.network/other/681606734/61811a42-c975-4bd4-bf09-a96840928a7c-original.webp"};
  GAMES.filter(g=>g.slug!==game.slug).forEach(g=>{
    const a=document.createElement("a");
    a.className="other-game-card";
    a.href=gamePath(g);
    a.dataset.slug=g.slug;
    a.innerHTML=`<div class="other-game-image"><img src="${squareImages[g.slug] || g.image}" alt="${g.name}" loading="lazy" decoding="async"></div><h3></h3>`;
    a.querySelector("h3").textContent=g.name;
    grid.appendChild(a);
  });
}
function openGame(game,push=true){
  window.ZAMN_CURRENT_GAME = game;
  setPageIcon(game.icon || game.image);
  if(!game||!gameView)return;
  setText("detailTitle",game.name);
  setText("detailSubtitle", ({"horof-bell":"تحدي الخلية","horof":"تحدي الحروف","photos-1":"تقدر تجيب الحل بسرعة؟","photos-2":"تحدي الصور أبو عمر","photos-3":"تقدر تجيب الصورة؟","family-feud":"تحدي العائلة","fawazeer":"تحدي الأسئلة","guess-link":"تحدي الرابط","alatrash":"اتحداك تجيب الأطرش","top-ten":"تحدي الـ10 إجابات","mn-ana":"تحدي المعرفة","aljawab-almajhool":"مين صاحب الجواب؟"})[game.slug] || game.badge || game.category || "تحدي جماعي");
  setText("detailDesc",game.description);
  setText("detailPlayers",game.players || "٢+ لاعبين");
  setText("detailCategory",game.category || game.badge || "لعبة جماعية");
  setText("detailStatus",game.status || "متاحة الآن");

  // تقييم صفحة اللعبة فقط — لا يغيّر تقييم بطاقات الصفحة الرئيسية.
  const PAGE_RATINGS = {
    "horof-bell":"5",
    "horof":"5",
    "photos-1":"4.7",
    "photos-2":"5",
    "photos-3":"5",
    "family-feud":"4.9",
    "fawazeer":"5"
  };
  const infoRow=document.querySelector("#gameView .retro-info-row");
  let detailRating=document.getElementById("detailRating");
  const pageRating=game.storeRating || "";
  if(infoRow){
    if(pageRating){
      if(!detailRating){
        detailRating=document.createElement("div");
        detailRating.id="detailRating";
        detailRating.className="retro-info-card retro-rating-card";
        infoRow.appendChild(detailRating);
      }
      detailRating.textContent=`★ ${pageRating}`;
      detailRating.setAttribute("aria-label",`تقييم اللعبة ${pageRating} من 5`);
      detailRating.hidden=false;
      infoRow.classList.add("has-rating");
    }else{
      if(detailRating) detailRating.remove();
      infoRow.classList.remove("has-rating");
    }
  }
  const play=document.getElementById("gamePlayBtn");
  const buy=document.getElementById("gameBuyBtn");
  const trial=document.getElementById("gameTrialBtn");
  if(play){play.href="#"; play.removeAttribute("target"); play.textContent="▶ العب الآن"}
  if(buy){
    const hasBuy=!!(game.buyLink && game.price);
    buy.hidden=!hasBuy;
    if(hasBuy){buy.href=game.buyLink; buy.target="_blank"; buy.rel="noopener"; buy.textContent=`💳 اشتر الآن - ${game.price}`}
  }
  if(trial){trial.dataset.trialKey=game.trialKey||""}
  if(window.setupProductDesign) window.setupProductDesign(game);
  renderShots(game);
  renderReviews(game);
  renderOtherGames(game);
  renderSeoRelated(game);
  const aljawabSpaInfo=document.getElementById("aljawabSpaInfo");
  if(aljawabSpaInfo) aljawabSpaInfo.hidden = game.slug !== "aljawab-almajhool";

  // مميزات «من أنا؟» خاصة بهذه اللعبة فقط عند التنقل داخل صفحة اللعبة.
  const mnAnaFeaturesTitle=document.getElementById("mnAnaFeaturesTitle") || document.querySelector(".mnana-cartoon-features-title");
  const mnAnaFeatures=document.querySelector(".mnana-cartoon-features");
  const isMnAna=game.slug==="mn-ana";
  if(mnAnaFeaturesTitle) mnAnaFeaturesTitle.hidden=!isMnAna;
  if(mnAnaFeatures) mnAnaFeatures.hidden=!isMnAna;

  const horofBellFaq = document.getElementById("horofBellFaq");
  const horofBellHowTo = document.getElementById("horofBellHowTo");
  const horofBellHeroVisual = document.getElementById("horofBellHeroVisual");
  const isHorofBell = game.slug === "horof-bell";
  if(horofBellFaq) horofBellFaq.hidden = !isHorofBell;
  if(horofBellHowTo) horofBellHowTo.hidden = !isHorofBell;
  if(horofBellHeroVisual) horofBellHeroVisual.hidden = !isHorofBell;
  document.body.classList.toggle("horof-bell-mode", isHorofBell);

  setSEO(game);
  document.body.classList.add("game-mode");
  gameView.hidden=false;
  window.scrollTo({top:0,behavior:"auto"});
  if(push) history.pushState({view:"game",slug:game.slug},"",gamePath(game));
}
window.openGame = openGame;

function closeGame(push=true){
  if(!document.getElementById("homeMain")){
    window.location.href="/";
    return;
  }
  window.ZAMN_CURRENT_GAME = null;
  setPageIcon("https://zamn.games/favicon.png?v=10");
  document.body.classList.remove("game-mode","horof-bell-mode","family-design");
  const reviewGrid=document.getElementById("retroReviewsGrid");
  if(reviewGrid?.reviewCleanup) reviewGrid.reviewCleanup();
  const aljawabSpaInfo=document.getElementById("aljawabSpaInfo");
  if(aljawabSpaInfo) aljawabSpaInfo.hidden=true;
  const horofBellFaq = document.getElementById("horofBellFaq");
  const horofBellHowTo = document.getElementById("horofBellHowTo");
  const horofBellHeroVisual = document.getElementById("horofBellHeroVisual");
  if(horofBellFaq) horofBellFaq.hidden = true;
  if(horofBellHowTo) horofBellHowTo.hidden = true;
  if(horofBellHeroVisual) horofBellHeroVisual.hidden = true;
  if(gameView) gameView.hidden=true;
  resetSEO();
  window.scrollTo({top:0,behavior:"auto"});
  if(push) history.pushState({view:"home"},"","/");
}
document.addEventListener("click",e=>{
  const link=e.target.closest('a[href]');
  if(!link)return;
  const href=link.getAttribute("href");
  if(!href || !href.startsWith("/"))return;
  const game=gameByPath(href.split("?")[0].split("#")[0]);
  if(!game)return;
  e.preventDefault();
  openGame(game,true);
});
document.getElementById("gameBackBtn")?.addEventListener("click",()=>closeGame(true));


const faqMoreBtn=document.getElementById("faqMoreBtn");
if(faqMoreBtn){
  faqMoreBtn.addEventListener("click",()=>{
    const extras=[...document.querySelectorAll("#faq .faq-extra")];
    const willShow=extras.some(el=>el.hidden);
    extras.forEach(el=>el.hidden=!willShow);
    faqMoreBtn.textContent=willShow ? "إظهار أقل" : "إظهار المزيد";
    faqMoreBtn.setAttribute("aria-expanded",willShow ? "true" : "false");
  });
}

window.addEventListener("popstate",(event)=>{
  const pathGame=gameByPath(location.pathname);
  if(pathGame){ openGame(pathGame,false); return; }
  if(event.state && event.state.view==="game" && event.state.slug){
    const g=bySlug(event.state.slug);
    if(g){ openGame(g,false); return; }
  }
  closeGame(false);
});
const initialGame=gameByPath(location.pathname);
if(initialGame) openGame(initialGame,false);

let lightbox;
function openLightbox(src,alt){
  if(!lightbox){
    lightbox=document.createElement("div");
    lightbox.className="zamn-lightbox";
    lightbox.innerHTML='<img alt="">';
    lightbox.addEventListener("click",()=>lightbox.classList.remove("open"));
    document.body.appendChild(lightbox);
  }
  const img=lightbox.querySelector("img");
  img.src=src; img.alt=alt||"صورة اللعبة";
  lightbox.classList.add("open");
}


document.addEventListener("DOMContentLoaded",()=>{
  const path=window.location.pathname;
  if(!gameByPath(path)){
    setPageIcon("https://zamn.games/favicon.png?v=10");
  }
});
